import{_ as e,o as l,c as a,a as t}from"./chunks/framework.Ld7uezS_.js";const p=JSON.parse('{"title":"其他消防设施设备级课程成果概览","description":"","frontmatter":{},"headers":[],"relativePath":"outputs/overview-2026-08-21-other-device-cards.md","filePath":"outputs/overview-2026-08-21-other-device-cards.md","lastUpdated":1787290310000}'),o={name:"outputs/overview-2026-08-21-other-device-cards.md"};function r(d,i,c,s,n,h){return l(),a("div",null,[...i[0]||(i[0]=[t('<h1 id="其他消防设施设备级课程成果概览" tabindex="-1">其他消防设施设备级课程成果概览 <a class="header-anchor" href="#其他消防设施设备级课程成果概览" aria-label="Permalink to &quot;其他消防设施设备级课程成果概览&quot;">​</a></h1><h2 id="本轮目标" tabindex="-1">本轮目标 <a class="header-anchor" href="#本轮目标" aria-label="Permalink to &quot;本轮目标&quot;">​</a></h2><p>继续按零基础设备卡审查其他消防设施，避免把“风机启动”“灯具点亮”“电话有声音”“电梯收到迫降信号”等单个现象直接写成系统功能合格。</p><h2 id="本轮完成" tabindex="-1">本轮完成 <a class="header-anchor" href="#本轮完成" aria-label="Permalink to &quot;本轮完成&quot;">​</a></h2><p>在 <code>skill/other-facilities.md</code> 新增七类设备学习卡：</p><ol><li>防烟排烟设施；</li><li>防火门、防火卷帘和防火阀；</li><li>应急照明与疏散指示；</li><li>消防电话与应急广播；</li><li>消防电梯迫降；</li><li>灭火器；</li><li>室内消火栓组件。</li></ol><p>每类设备均补充：</p><ul><li>主要作用；</li><li>组成部件；</li><li>工作原理；</li><li>正常证据；</li><li>异常处理；</li><li>安全边界；</li><li>恢复和记录要求。</li></ul><h2 id="重点辨析" tabindex="-1">重点辨析 <a class="header-anchor" href="#重点辨析" aria-label="Permalink to &quot;重点辨析&quot;">​</a></h2><ul><li>加压送风和排烟服务的区域、目的和动作逻辑不同；</li><li>防火门、防火卷帘、防火阀分别对应门洞、大洞口和风管分隔；</li><li>应急照明解决“看得见”，疏散指示解决“往哪里走”；</li><li>消防电话验证双向通话，广播验证分区播报和强制切换；</li><li>消防电梯迫降是专业接口验证，不是普通电气启停；</li><li>灭火器外观正常不等于灭火功能合格；</li><li>消火栓组件齐全不等于供水和反馈链正常。</li></ul><h2 id="同步文件" tabindex="-1">同步文件 <a class="header-anchor" href="#同步文件" aria-label="Permalink to &quot;同步文件&quot;">​</a></h2><ul><li><code>training-skill.md</code>：新增其他设施七类设备复述清单；</li><li><code>standard-mapping.md</code>：同步 2.3、3.3、4.3、5.3；</li><li><code>knowledge-coverage-matrix.md</code>：更新设备级覆盖状态；</li><li><code>overview.md</code> 与项目工作日志。</li></ul><h2 id="边界说明" tabindex="-1">边界说明 <a class="header-anchor" href="#边界说明" aria-label="Permalink to &quot;边界说明&quot;">​</a></h2><p>涉及风量、风压、照度、转换时间、持续时间、动作时间、维修权限和电梯安全逻辑时，必须根据现行标准、设计文件、设备说明书、检测方案和专业协同要求核验，不写成脱离场景的统一参数。</p>',14)])])}const m=e(o,[["render",r]]);export{p as __pageData,m as default};
